package campusloop;
import java.sql.*;import java.nio.file.*;import java.time.*;import java.util.*;
public final class Database {
 private final String url;
 private final String username,password;
 private final boolean postgres;
 public Database(Path dir)throws Exception{
 String remote=System.getenv("JDBC_DATABASE_URL");
 postgres=remote!=null&&!remote.isBlank();
 if(postgres){
  if(!remote.startsWith("jdbc:postgresql://"))throw new IllegalArgumentException("JDBC_DATABASE_URL must start with jdbc:postgresql://");
  url=remote;username=System.getenv("DATABASE_USER");password=System.getenv("DATABASE_PASSWORD");
  if(username==null||username.isBlank()||password==null||password.isBlank())throw new IllegalStateException("Set DATABASE_USER and DATABASE_PASSWORD as hosting secrets");
 }else{
  if(Boolean.parseBoolean(System.getenv().getOrDefault("REQUIRE_EXTERNAL_DB","false")))throw new IllegalStateException("Set JDBC_DATABASE_URL, DATABASE_USER and DATABASE_PASSWORD before cloud deployment. Local H2 is disabled in cloud mode.");
  Files.createDirectories(dir);url="jdbc:h2:file:"+dir.resolve("campusloop").toAbsolutePath()+";DB_CLOSE_ON_EXIT=FALSE";username="sa";password="";
 }
 try(var c=connect();var s=c.createStatement()){
 s.execute("CREATE TABLE IF NOT EXISTS users(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,student_id VARCHAR(40) UNIQUE,department VARCHAR(80) NOT NULL,password_hash VARCHAR(200) NOT NULL,role VARCHAR(10) NOT NULL CHECK(role IN ('STUDENT','ADMIN')))");
 s.execute("CREATE TABLE IF NOT EXISTS events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,category VARCHAR(20) NOT NULL,description VARCHAR(2000) NOT NULL,starts_at VARCHAR(30) NOT NULL,venue VARCHAR(100) NOT NULL,capacity INT NOT NULL CHECK(capacity>0),status VARCHAR(12) DEFAULT 'OPEN' NOT NULL CHECK(status IN ('OPEN','CANCELLED')))");
 s.execute("CREATE TABLE IF NOT EXISTS registrations(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_id BIGINT NOT NULL REFERENCES events(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id),registered_at VARCHAR(40) NOT NULL,attended BOOLEAN NOT NULL DEFAULT FALSE,UNIQUE(event_id,user_id))");
 if(((Number)query(c,"SELECT COUNT(*) n FROM events").get(0).get("n")).intValue()==0){String[][] sample={{"CodeSprint 2026","Technical","A collaborative coding challenge. Bring your laptop, curiosity, and your best ideas.","Innovation Lab · Block A","120"},{"Unplugged: The Campus Sessions","Cultural","An evening of acoustic music and student performances.","Open Air Amphitheatre","300"},{"Interdepartment Sports Meet","Sports","Represent your department in a day of friendly competition.","Main Sports Ground","200"},{"Design Thinking Bootcamp","Workshop","Learn a practical process for solving real problems, from discovery to prototype.","Seminar Hall · Block B","60"},{"The Green Campus Drive","Community","Join a campus clean-up and tree planting session. All supplies provided.","Central Courtyard","150"},{"Startup Stories & Coffee","Technical","Meet student founders and exchange ideas over coffee.","Entrepreneurship Cell","80"}};int i=0;for(var e:sample)update(c,"INSERT INTO events(name,category,description,starts_at,venue,capacity) VALUES(?,?,?,?,?,?)",e[0],e[1],e[2],LocalDate.now().plusDays(7+(i++)*2).atTime(10,0).toString(),e[3],Integer.valueOf(e[4]));}
 }}
 public Connection connect()throws SQLException{var props=new Properties();props.setProperty("user",username);props.setProperty("password",password);if(postgres){props.setProperty("connectTimeout","15");props.setProperty("socketTimeout","30");props.setProperty("prepareThreshold","0");}return DriverManager.getConnection(url,props);}
 public static List<Map<String,Object>> query(Connection c,String sql,Object...args)throws SQLException{try(var p=c.prepareStatement(sql)){bind(p,args);try(var r=p.executeQuery()){var out=new ArrayList<Map<String,Object>>();while(r.next()){var m=new LinkedHashMap<String,Object>();for(int i=1;i<=r.getMetaData().getColumnCount();i++)m.put(r.getMetaData().getColumnLabel(i).toLowerCase(Locale.ROOT),r.getObject(i));out.add(m);}return out;}}}
 public static int update(Connection c,String sql,Object...args)throws SQLException{try(var p=c.prepareStatement(sql)){bind(p,args);return p.executeUpdate();}}
 private static void bind(PreparedStatement p,Object[]args)throws SQLException{for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);}
}
